record={'collector_path':cmd[2],'collector_sha256':sha(pathlib.Path(cmd[2]).read_bytes()),'argv':cmd,'actual_exit':r.returncode,'summary':{k:s[k] for k in ['runtime_exit_code','runner_exit_code','agent_status','validation_status','result_status','terminal','diagnostic_counts','canary_status','canary_read_candidate','events','tool_results']},'unique_terminal_line':term[0],'final_line':finals[-1][0],'final_sha256':sha(s['final_answer'].encode()),'retained_notices':retained,'checks':checks,'sources_sha256':before,'source_integrity_after':after,'business_disposition':'Developer and Judge remain caller-unaccepted candidates; collector replay is technical completion only, not business validation'}
pathlib.Path(a.save).write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'summary':record['summary'],'checks':checks},ensure_ascii=False,indent=2));assert all(checks.values()),checks
